<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $itemId=(int)($d['item_id']??0); $action=(string)($d['action']??''); if(!in_array($action,['approve','reject'],true)){ApiResponse::validation(['action'=>'Invalid action.']);exit;} $s=$db->prepare('SELECT ji.*,j.owner_id FROM journey_items ji INNER JOIN journeys j ON j.id=ji.journey_id WHERE ji.id=:id AND ji.deleted_at IS NULL LIMIT 1'); $s->execute(['id'=>$itemId]); $item=$s->fetch(PDO::FETCH_ASSOC); if(!$item){ApiResponse::notFound('Item not found.');exit;} if((int)$item['owner_id']!==$uid&&!SessionHelper::isAdmin()){ApiResponse::forbidden('Only owner can review.');exit;} $status=$action==='approve'?'approved':'rejected'; $u=$db->prepare('UPDATE journey_items SET status=:status WHERE id=:id'); $u->execute(['status'=>$status,'id'=>$itemId]); NotificationService::createOnce($db,(int)$item['contributor_id'],$uid,NotificationService::TYPE_JOURNEY_INVITATION,'journey',(int)$item['journey_id'],$status==='approved'?'approved your journey contribution.':'rejected your journey contribution.'); ApiResponse::success([],'Contribution reviewed.'); }catch(Throwable $e){Logger::error('Journey review item failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to review item.');}
?>
